import React, { useState, useEffect, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import { Search, MapPin, ChevronDown } from 'lucide-react';
import { searchCities, getFilters } from '../services/api';
import styles from './HeroSearch.module.css';

export default function HeroSearch() {
  const navigate = useNavigate();
  const [mode,          setMode]          = useState('Buy');
  const [city,          setCity]          = useState('');
  const [citySuggestions, setCitySuggestions] = useState([]);
  const [propertyType,  setPropertyType]  = useState('');
  const [filters,       setFilters]       = useState({ propertyTypes: [], budgetRanges: [] });
  const [budget,        setBudget]        = useState('');

  useEffect(() => {
    getFilters().then(({ data }) => setFilters(data)).catch(() => {});
  }, []);

  const handleCityChange = useCallback(async (e) => {
    const val = e.target.value;
    setCity(val);
    if (val.length >= 2) {
      try {
        const { data } = await searchCities(val);
        setCitySuggestions(data.cities || []);
      } catch { setCitySuggestions([]); }
    } else {
      setCitySuggestions([]);
    }
  }, []);

  const handleSearch = (e) => {
    e.preventDefault();
    const params = new URLSearchParams();
    if (mode)         params.set('listingType', mode === 'Buy' ? 'Sell' : 'Rent');
    if (city)         params.set('city', city);
    if (propertyType) params.set('propertyType', propertyType);
    if (budget)       params.set('budget', budget);
    navigate('/search?' + params.toString());
  };

  return (
    <div className={styles.wrap}>
      {/* Heading */}
      <div className={styles.heading}>
        <h1 className={styles.h1}>Find Your <span className={styles.accent}>Dream Property</span></h1>
        <p className={styles.sub}>Discover verified homes, plots & commercial spaces across India</p>
      </div>

      {/* Mode Tabs */}
      <div className={styles.tabs}>
        {['Buy', 'Rent'].map(m => (
          <button
            key={m}
            className={`${styles.tab} ${mode === m ? styles.tabActive : ''}`}
            onClick={() => setMode(m)}
          >{m}</button>
        ))}
      </div>

      {/* Search Form */}
      <form className={styles.form} onSubmit={handleSearch}>
        {/* City */}
        <div className={styles.cityWrap}>
          <MapPin size={16} className={styles.cityIcon} />
          <input
            type="text"
            value={city}
            onChange={handleCityChange}
            placeholder="City or Locality..."
            className={styles.cityInput}
            autoComplete="off"
          />
          {citySuggestions.length > 0 && (
            <ul className={styles.suggestions}>
              {citySuggestions.map(c => (
                <li key={c} className={styles.suggestion} onClick={() => { setCity(c); setCitySuggestions([]); }}>
                  <MapPin size={13} /> {c}
                </li>
              ))}
            </ul>
          )}
        </div>

        {/* Property Type */}
        <div className={styles.selectWrap}>
          <select value={propertyType} onChange={e => setPropertyType(e.target.value)} className={styles.select}>
            <option value="">Property Type</option>
            {filters.propertyTypes.map(t => (
              <option key={t.id} value={t.id}>{t.label}</option>
            ))}
          </select>
          <ChevronDown size={15} className={styles.chevron} />
        </div>

        {/* Budget */}
        <div className={styles.selectWrap}>
          <select value={budget} onChange={e => setBudget(e.target.value)} className={styles.select}>
            <option value="">Budget</option>
            {filters.budgetRanges.map(b => (
              <option key={b.id} value={b.id}>{b.label}</option>
            ))}
          </select>
          <ChevronDown size={15} className={styles.chevron} />
        </div>

        <button type="submit" className={styles.searchBtn}>
          <Search size={18} />
          Search
        </button>
      </form>

      {/* Quick links */}
      <div className={styles.quickLinks}>
        <span className={styles.qlLabel}>Popular:</span>
        {['Bengaluru', 'Mumbai', 'Hyderabad', 'Chennai', 'Pune'].map(c => (
          <button
            key={c}
            className={styles.qlChip}
            onClick={() => navigate(`/search?city=${c}`)}
          >{c}</button>
        ))}
      </div>
    </div>
  );
}
